# 2.1 通过 ACK API 授权 RAM 用户
aliyun cs POST /clusters/<cluster_id>/grant_permissions --body '{
  "body": [
    {
      "user_id": "<ram-user-id>",
      "permissions": [
        {
          "cluster": "<cluster_id>",
          "role_type": "cluster",
          "role_name": "dev",
          "namespace": "team-dev",
          "is_custom": false,
          "is_ram_role": false
        }
      ]
    }
  ]
}'

# 2.2 查看用户权限
aliyun cs GET /clusters/<cluster_id>/grant_permissions

